+/// Feature-only source handles, recorded at the actual constraint calls.
+/// No witness closures are evaluated and no values/nodes/assertions are added.
+#[cfg(feature = "formal-observer")]
+pub mod inspection {
+    use super::*;
+    use commonware_cryptography::zk::circuit::CircuitIdx;
+    use std::cell::RefCell;
+    thread_local! {
+        static HANDLES: RefCell<Option<Vec<(&'static str, Vec<CircuitIdx>, Vec<CircuitIdx>)>>> = const { RefCell::new(None) };
+    }
+    pub struct Capture { _thread: std::marker::PhantomData<std::rc::Rc<()>> }
+    impl Drop for Capture {
+        fn drop(&mut self) { HANDLES.with(|handles| *handles.borrow_mut() = None); }
+    }
+    pub fn begin() -> Result<Capture> {
+        HANDLES.with(|handles| {
+            let mut handles = handles.borrow_mut();
+            ensure!(handles.is_none(), "nested balance capture");
+            *handles = Some(Vec::new());
+            Ok(Capture { _thread: std::marker::PhantomData })
+        })
+    }
+    pub(super) fn record(role: &'static str, values: &[Var<'_, Scalar>], bits: &[BoolVar<'_, Scalar>]) {
+        HANDLES.with(|handles| {
+            let mut handles = handles.borrow_mut();
+            let Some(handles) = handles.as_mut() else { return; };
+            assert!(handles.len() < 5, "unexpected additional balance gadget");
+            handles.push((role,
+                values.iter().map(|value| value.inspect_circuit_idx().expect("native balance handle")).collect(),
+                bits.iter().map(|bit| bit.var().inspect_circuit_idx().expect("native balance bit")).collect()));
+        });
+    }
+    pub fn take() -> Vec<(&'static str, Vec<CircuitIdx>, Vec<CircuitIdx>)> {
+        HANDLES.with(|handles| std::mem::take(handles.borrow_mut().as_mut().expect("inactive balance capture")))
+    }
+    #[cfg(test)]
+    mod tests {
+        use super::*;
+        #[test]
+        fn capture_cleanup_on_success_error_and_panic() {
+            { let _capture = begin().unwrap(); assert!(begin().is_err()); }
+            { let _capture = begin().unwrap(); assert!(take().is_empty()); }
+            let failure = std::panic::catch_unwind(|| { let _capture = begin().unwrap(); panic!("synthetic capture failure"); });
+            assert!(failure.is_err());
+            let _capture = begin().unwrap();
+            assert!(take().is_empty());
+        }
+    }
 }

